import React, { useState, useEffect } from "react";

export default function UserProfileCard({ token, setMsg }) {
  const [profile, setProfile] = useState(null);

  useEffect(() => {
    if (!token) return;

    const fetchProfile = async () => {
      try {
        // Try fetching /me first (works for Volunteer/Donor)
        let res = await fetch(
          (process.env.REACT_APP_API || "http://localhost:4000") + "/api/me",
          { headers: { Authorization: `Bearer ${token}` } }
        );
        let data = await res.json();

        if (data.user) {
          setProfile({
            name: data.user.name,
            email: data.user.email,
            role: data.user.role,
            points: data.user.points,
          });
        } else {
          // If /me doesn't return user, try /ngo/info (works for NGOs)
          res = await fetch(
            (process.env.REACT_APP_API || "http://localhost:4000") + "/api/ngo/info",
            { headers: { Authorization: `Bearer ${token}` } }
          );
          data = await res.json();
          if (data.id) {
            setProfile({
              name: data.name,
              email: data.email,
              role: "NGO",
              totalEvents: data.totalEvents,
            });
          } else {
            setMsg && setMsg("Unable to fetch profile");
          }
        }
      } catch (e) {
        console.error("Profile fetch error:", e);
        setMsg && setMsg("Error fetching profile");
      }
    };

    fetchProfile();
  }, [token, setMsg]);

  if (!profile)
    return (
      <div
        style={{
          width: "100%",
          height: 180,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          border: "1px solid #ccc",
          borderRadius: 8,
        }}
      >
        Loading profile...
      </div>
    );

  return (
    <div
      style={{
        border: "1px solid #ccc",
        borderRadius: 8,
        padding: 16,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: 12,
      }}
    >
      <div
        style={{
          width: 80,
          height: 80,
          borderRadius: "50%",
          backgroundColor: "#eee",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          fontSize: 32,
          fontWeight: "bold",
          color: "#888",
        }}
      >
        {profile.name ? profile.name[0].toUpperCase() : "?"}
      </div>
      <div style={{ fontWeight: 600 }}>{profile.name}</div>
      <div style={{ fontSize: 14, color: "#555" }}>{profile.email}</div>
      <div style={{ fontSize: 13, color: "#777" }}>{profile.role}</div>
      {profile.points !== undefined && (
        <div style={{ fontSize: 14, marginTop: 8 }}>Points: {profile.points}</div>
      )}
      {profile.totalEvents !== undefined && (
        <div style={{ fontSize: 14, marginTop: 8 }}>Total Events: {profile.totalEvents}</div>
      )}
    </div>
  );
}
